import asynciofrom asyncio import QueueEmptyimport aiohttp.webimport sysimport timeimport requestsimport pg_generalimport jsonfrom enum import IntEnumimport apirouteimport serverconfimport pg_getselfipimport env_settingfrom pg_redis import PGRedisfrom pg_ga import PG_GAfrom datetime import datetime,timedeltaclass Message:    def __init__(self, type, msg, name="0"):        self.type = type        self.msg = msg        self.name = nameclass ClientInfo:    def __init__(self, logintoken, ws, ip,region='',region_sub='',city=''):        self.logintoken = logintoken        self.client_ws = ws        self.memberid = None        self.ip = ip        self.task = None        self.queue = asyncio.Queue(maxsize=-1)        self.region = region        self.region_sub = region_sub        self.city = city        self.ga_obj = PG_GA(self.ip,memberid=int(time.time()%86400*1000))        self.syncdatetime = datetime.utcnow()        self.channelindex = None        self.logintime = None        self.joinedgameid = ''        self.joinedhall = 0       # 0 金幣 , 1: 銀幣        self.seatnum = 0            # 座位號碼        self.gamelogdataindex = 0        self.joinedgametime = None    def __del__(self):        del self.ga_obj        del self.queue        if self.task is not None:            self.task.cancel()        pg_general.writelog(pg_general.PG_LogerLevel.info,                            'ClientInfo del memberid:{0},logintoken:{1},task:{2}'.format(self.memberid,self.logintoken,self.task))    def setmemberid(self, memberid):        self.memberid = memberid    def settask(self,task):        self.task = task    def setchannel(self,channelindex):        self.channelindex = channelindex    def setlogintime(self, logintime):        self.logintime = logintimeclass SendMsgType(IntEnum):    server_to_all_client = 0    server_to_client = 1    server_to_channel = 2PORT = serverconf.PORTcommandlist = apiroute.commandlist############################# for loadbalancer healthy check ############################async def healthycheck_handler(request):    return aiohttp.web.Response(text='check')###############################concurrent user amount check ################################async def concurrent_user_handler(request):    app = request.app    redis_object = app['redis']    check_flag = request.rel_url.query.get('checkflag')    concurrent_user = 0    if check_flag is not None:        concurrent_user = len(app['client_dict'])    else:        concurrent_user = await redis_object.get_value("concurrent_user")        if concurrent_user is None:            concurrent_user = 0    return  aiohttp.web.Response(text=str(concurrent_user))async def headline_handler(request):    app = request.app    type = int(request.match_info["type"])    msg = await request.json()    logintoken = None    if type == 0:        type = SendMsgType.server_to_all_client    else:        type = SendMsgType.server_to_client        logintoken = request.rel_url.query.get('logintoken')    msgdict ={        "type": type,        "msg": msg,        "logintoken": logintoken    }    # 新增訊息    await app["broadcast_queue"].put(msgdict)    return aiohttp.web.json_response({"status_code":0})# 每一個 ws connection 都會有一個 task futureasync def client_queue_task(app,logintoken):    run_flag = True    q = app["client_dict"][logintoken].queue    ws = app["client_dict"][logintoken].client_ws    while(run_flag):        try:            msg_info = await q.get()            cmd = msg_info.get('cmd')            memberid = msg_info.get('memberid')            # initial vars.            exppercent = None            levelup = None            level = None            multipiler = None            total_win = None            total_bet = None            bonus_win = None            base_win = None            senddata = {}            if cmd == 'bet':                exppercent = msg_info.get('exppercent')                levelup = msg_info.get('levelup')                level = msg_info.get('level')                exptonextlevel = msg_info.get('exptonextlevel')                maxbet = msg_info.get('maxbet')                unlockgame = msg_info.get('unlockgame')                senddata = {                    "commandid": 3000002,                    "exppercent": exppercent,                    "levelup": levelup,                    "level": level,                    "exptonextlevel": exptonextlevel,                    "maxbet": maxbet,                    "unlockgame": unlockgame                }                await ws.send_json(senddata)            elif cmd == 'result':                hallid = msg_info.get('hallid')                gameid = msg_info.get('gameid')                seatnum = msg_info.get('seatnum')                unopenturn = msg_info.get('unopenturn')                avgturn = msg_info.get('avgturn')                his1turn = msg_info.get('his1turn')                his2turn = msg_info.get('his2turn')                his3turn = msg_info.get('his3turn')                his1multi = msg_info.get('his1multi')                his2multi = msg_info.get('his2multi')                his3multi = msg_info.get('his3multi')                senddata = {                    "commandid": 3000002,                    "hallid": hallid,                    "gameid": gameid,                    "seatnum": seatnum,                    "unopenturn": unopenturn,                    "avgturn": avgturn,                    "his1turn": his1turn,                    "his2turn": his2turn,                    "his3turn": his3turn,                    "his1multi": his1multi,                    "his2multi": his2multi,                    "his3multi": his3multi                }                await ws.send_json(senddata)            pg_general.writelog(pg_general.PG_LogerLevel.info,                                'client_queue_task queue info : {0}, memberid: {1}, logintoken : {2},senddata: {3}'.format(msg_info, memberid, logintoken,senddata))        except Exception as e:            pg_general.writelog(pg_general.PG_LogerLevel.info,                                'client_queue_task except : {0} , logintoken:{1}'.format(e , logintoken))            run_flag = False        finally:            await asyncio.sleep(0.01)    pg_general.writelog(pg_general.PG_LogerLevel.info,'client_queue_task exit logintoen: {0}'.format(logintoken))async def save_redis_online(app,redis,memberid,logintoken,selflobbyserverip):    try:        await redis.set_value('online_'+ str(memberid),selflobbyserverip,15)        # await redis.set_value(str(memberid),logintoken,180)        await redis.expire(str(memberid),180)        memberchannel = await redis.get_all_keys('channel_*_{}'.format(memberid))        if memberchannel is not None:            if len(memberchannel) == 1:                await redis.set_value(memberchannel[0],'1',180)                app["client_dict"][logintoken].setchannel(int(memberchannel[0].split('_')[1]))        nowtwtime = pg_general.get_tw_datetime()        logintime = app["client_dict"][logintoken].logintime        if (nowtwtime-logintime).total_seconds()>=15: # 已經登入 15 秒以上 , 可以抓客服傳送的資料            llen = await redis.llen('servicechat_{}'.format(memberid))            if llen >0:                contentlist = []                for i in range(llen):                    content = await redis.rpop('servicechat_{0}'.format(memberid))                    if content is not None:                        contentlist.append(str(content, encoding = "utf-8"))                if len(contentlist)> 0:                    ws = app["client_dict"][logintoken].client_ws                    sendmsg = {                        "commandid":3000012,                        "data":{                            "time": nowtwtime.strftime('%Y-%m-%d %H:%M:%S'),                            "contentlist": contentlist                        }                    }                    await ws.send_json(sendmsg)    except ValueError as e:        pg_general.writelog(pg_general.PG_LogerLevel.error, 'save_redis_online valueerror: {0}'.format(e))    except Exception as e:        pg_general.writelog(pg_general.PG_LogerLevel.error, 'save_redis_online except: {0}'.format(e))async def websocket_handler(request):    try:        # 連線交握        app = request.app        ws = aiohttp.web.WebSocketResponse()        logintoken = pg_general.generatorsha256()        selflobbyserverip =app['selfip'] + ':{}'.format(app['port'])        redis = app['redis']        try:            await ws.prepare(request)        except Exception as e:      # handle http request not websocket request by gorden            del ws            ws = None            return aiohttp.web.Response(status=404,text='404: Not Found')        pg_general.writelog(pg_general.PG_LogerLevel.info, 'Websocket connection ready:{0}'.format(logintoken))        # 檢查連線是否重複        if logintoken in app["client_dict"]:            # print('name in client_dict already exists')            pg_general.writelog(pg_general.PG_LogerLevel.error, 'client_dict already exists logintoken:{0}'.format(logintoken))            await app["client_dict"][logintoken].client_ws.close()        # 記錄連線資訊        user_region = request.headers.get('X-Client-Geo-Region', None)       # 抓 user region        user_region_sub = request.headers.get('X-Client-Geo-Region-Sub',None)        user_city = request.headers.get('X-Client-Geo-City', None)           # 抓 user city        user_ip = request.headers.get('X-Forwarded-For',None)               # 抓 user ip        if user_ip is not None:            user_ip = user_ip.split(',')[0]        else:            user_ip = request.remote        if user_ip is None:            user_ip = '114.33.71.4'        app["client_dict"][logintoken] = ClientInfo(logintoken, ws, user_ip ,user_region,user_region_sub,user_city)        app["client_dict"][logintoken].settask(asyncio.ensure_future(client_queue_task(app,logintoken)))    except requests.Timeout as e:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'websocket_handler... requests.Timeout:{0}'.format(e))    except requests.TooManyRedirects as e:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'websocket_handler... requests.TooManyRedirects:{0}'.format(e))    except requests.HTTPError as e:        # 404, 503, 500, 403 etc.        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'websocket_handler... requests.HTTPError:{0}'.format(e))    except requests.RequestException as e:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'websocket_handler... requests.RequestException:{0}'.format(e))    except Exception as e:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'websocket_handler... all except:{0}'.format(sys.exc_info()[0]))    # 接收訊息    try:        async for msg in ws:            if msg.type == aiohttp.WSMsgType.TEXT:                if msg.data in ['x','xx']:                    app["client_dict"][logintoken].syncdatetime = datetime.utcnow()                    await ws.send_str('y')                    memberid =  app["client_dict"][logintoken].memberid                    if memberid is not None:                        pg_general.writelog(pg_general.PG_LogerLevel.info,                                            '{}_{}'.format(msg.data,memberid))                        # asyncio.ensure_future(save_redis_online(app,redis,memberid,logintoken,selflobbyserverip))                        await save_redis_online(app, redis, memberid, logintoken, selflobbyserverip)                        if msg.data == 'xx':    # 在遊戲內                            gameid = app["client_dict"][logintoken].joinedgameid                            hallid = app["client_dict"][logintoken].joinedhall                            seatnum = app["client_dict"][logintoken].seatnum                            # print('xx_{},gameid:{},hallid:{}'.format(memberid,gameid,hallid))                            if gameid != '':                                if hallid == 0:                                    await redis.expire('seatsgold_{}@{}_{}'.format(gameid,seatnum,memberid),30)                                elif hallid ==1:                                    await redis.expire('seatssilver_{}@{}_{}'.format(gameid,seatnum,memberid),30)                                elif hallid ==2:                                    await redis.expire('seatstutorial_{}@{}_{}'.format(gameid,seatnum,memberid),30)                                elif hallid ==3: # fish gold                                    await redis.expire('fish_{}_{}_{}'.format('g',gameid,memberid), 15)                                elif hallid ==4: # fish silver                                    await redis.expire('fish_{}_{}_{}'.format('s',gameid,memberid), 15)                        elif msg.data == 'x':   # 在大廳                            gameid = app["client_dict"][logintoken].joinedgameid                            hallid = app["client_dict"][logintoken].joinedhall                            seatnum = app["client_dict"][logintoken].seatnum                            gamelogdataindex = app["client_dict"][logintoken].gamelogdataindex                            joinedgametime = app['client_dict'][logintoken].joinedgametime                            # 如果是 fish game , 至少要超過 4 秒 才可以call backtohall                            if hallid in [3,4]:                                nowutcdatetime = pg_general.getutcnowdatetime()                                if (nowutcdatetime - joinedgametime).total_seconds() < 4:                                    continue                            if gameid != '':        # 刪除佔位資料, 因為要判斷卡別資料,所以要丟給 apiserver 處理                                app["client_dict"][logintoken].joinedgameid = ''                                app["client_dict"][logintoken].joinedhall = 0                                app["client_dict"][logintoken].seatnum = 0                                app["client_dict"][logintoken].gamelogdataindex = 0                                # remove redis this game data                                if hallid ==0:                                    seatkey = 'gold'                                elif hallid ==1:                                    seatkey = 'silver'                                elif hallid ==2:                                    seatkey = 'tutorial'                                elif hallid ==3:                                    seatkey = 'fishg'                                elif hallid ==4:                                    seatkey = 'fishs'                                seat_data = 'seats{}_{}@{}_{}'.format(seatkey,gameid,seatnum,memberid)                                pg_general.writelog(pg_general.PG_LogerLevel.info,seat_data)                                await redis.del_key(seat_data)                                asyncio.ensure_future(apiroute.backtohall_future(app,redis,memberid,logintoken,gamelogdataindex,seat_data))                else:                    pg_general.writelog(pg_general.PG_LogerLevel.debug, 'recv:{0}'.format(msg))                    result = await recvmsg(app, logintoken, msg.data)                    if result is None or type(result) is str:                        raise Exception('duplicate login')                    else:                        await ws.send_json(result)                        pg_general.writelog(pg_general.PG_LogerLevel.debug, 'send:{0}'.format(result))            elif msg.type == aiohttp.WSMsgType.ERROR:                pg_general.writelog(pg_general.PG_LogerLevel.warn,                                    'websocket_handler aiohttp.WSMsgType.ERROR:{0}'.format(ws.exception()))            elif msg.type == aiohttp.WSMsgType.close:                pg_general.writelog(pg_general.PG_LogerLevel.warn,                                    'websocket_handler aiohttp.WSMsgType.close')            elif msg.type == aiohttp.WSMsgType.closed:                pg_general.writelog(pg_general.PG_LogerLevel.warn,                                    'websocket_handler aiohttp.WSMsgType.closed')            else:                pg_general.writelog(pg_general.PG_LogerLevel.warn,                                    'websocket_handler other msg.type msg:{0}'.format(msg))        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'websocket_handler Websocket connection closed,logintoken:{0}'.format(logintoken))    except asyncio.TimeoutError:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'websocket_handler TimeoutError,logintoken:{0}'.format(logintoken))    except asyncio.CancelledError:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'websocket_handler CancelledError:{0},logintoken:{1}'.format(sys.exc_info()[0],logintoken))    except Exception as e:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'websocket_handler all except:{0},logintoken:{1}'.format(sys.exc_info()[0],logintoken))    finally:        # 斷線處理        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            '{0} websocket_handler Someone disconnected:{1}'.format(time.strftime("%Y-%m-%d %X"),                                                                                    logintoken))        try:            await apiroute.backtohall_msghandler(app,logintoken,None)            if app["client_dict"][logintoken].memberid != None:                await app["logout_queue"].put({"memberid":app["client_dict"][logintoken].memberid,"logintoken":logintoken})        except:            pass        try:            await ws.close()        except:            pass        try:            del app["client_dict"][logintoken]        except:            pass        return wsasync def recvmsg(app, logintoken, msg):    result = None    statuscode = pg_general.Packagestatuscode.commanderror    redis = app['redis']    try:        # 拆解封包        parseresult, commandid, commandnum, data = parsecommand(msg)        if parseresult == True:            # 檢查 memberid 中的 logintoken 是否與現在的相同            if commandid  not in [1000000,1000001,1000036,1000065,1000066]:   # serverinfo, login , getaward , downloadsignal 不需要檢查                memberid = app["client_dict"][logintoken].memberid                if memberid is None:                    result = 'error:memberid is None'                    raise ValueError(result)                com_logintoken = await redis.get_value(memberid)                if com_logintoken != logintoken :                    result = 'error:logintoken different'                    raise ValueError(result)            # 根據commandid做對應的處理            if commandlist.get(commandid, None) != None:                clientdata, returncommandid, commandresult = await commandlist[commandid](app, logintoken, data)                statuscode = commandresult                # 打包封包                result = packagecommand(returncommandid, clientdata, statuscode, commandnum)            else:                pg_general.writelog(pg_general.PG_LogerLevel.warn,                                    "recvmsg parsemsg commandid not found, logintoken:{0}, msg:{1}".format(logintoken,                                                                                                           msg))        else:            pg_general.writelog(pg_general.PG_LogerLevel.warn,                                "recvmsg parsemsg parseresult==False, msg:{0}, logintoken:{1}".format(msg, logintoken))            result = msg    except Exception as e:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            "recvmsg parsemsg error:{0}, logintoken:{1}, msg:{2}".format(e, logintoken, msg))    except ValueError as e:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            "recvmsg parsemsg error:{0}, logintoken:{1}".format(e,logintoken,))    return resultdef parsecommand(msg):    result = False    commandid = None    commandnum = None    data = None    try:        recvjson = json.loads(msg)        commandid = recvjson.get("commandid")        commandnum = recvjson.get("commandnum")        data = recvjson.get("data")        if commandid != None and commandnum != None and data != None:            result = True        return result, commandid, commandnum, data    except Exception as e:        pg_general.writelog(pg_general.PG_LogerLevel.error,                            "parsecommand error, exception:{0},msg:{1}".format(e,msg))    return result, commandid, commandnum, datadef packagecommand(commandid, inputdata, statuscode, commandnum=0):    data = {        "commandid": commandid,        "data": inputdata,        "commandnum": commandnum,        "statuscode": statuscode,    }    return dataasync def broadcastloop(app):    while 1:        # 檢查是否有新訊息未推送        try:            q = app['broadcast_queue']            msg_info = await q.get()            if msg_info is None or msg_info == {}:                raise ValueError            # 檢查訊息類型為廣播或個人            if msg_info.get('type') == SendMsgType.server_to_all_client:                # 廣播訊息                await server_to_all_client(app, msg_info.get('msg'))            elif msg_info.get('type') == SendMsgType.server_to_channel:                # 頻道訊息                await server_to_channel(app,msg_info.get('msg'))            else:                # 單一玩家訊息                await server_to_client(app, msg_info.get('msg'), msg_info.get('logintoken'))        except QueueEmpty:            pass            #await server_to_all_client(app, {"commandid":3000000})        except ValueError:            pg_general.writelog(pg_general.PG_LogerLevel.error, 'broadcastloop ValueError:{0}'.format(sys.exc_info()[0]))        except Exception as e:            pg_general.writelog(pg_general.PG_LogerLevel.error, 'broadcastloop except:{0}'.format(sys.exc_info()[0]))        finally:            await asyncio.sleep(0)async def logoutloop(app):    while 1:        try:            q = app['logout_queue']            msg_info = await q.get()            memberid = msg_info.get('memberid')            logintoken = msg_info.get('logintoken')            await apiroute.logout_msghandler(memberid, logintoken)            pg_general.writelog(pg_general.PG_LogerLevel.warn, 'logoutloop msg_info:{0}'.format(msg_info))        except Exception as e:            pg_general.writelog(pg_general.PG_LogerLevel.error, 'logoutloop except:{0}'.format(sys.exc_info()[0]))        finally:            await asyncio.sleep(0)async def reddot_countdown_loop(app):    while 1:        try:            client_copy = app["client_dict"].copy()            if client_copy != {}:                for logintoken in client_copy:                    # 發送request到apiserver                    memberid = client_copy[logintoken].memberid                    if memberid is not None:                        # 檢查 memberid 裡面的 logintoken 是否與現在的一致                        redis = app['redis']                        cmp_logintoken = await redis.get_value(memberid)                        if cmp_logintoken != logintoken:                            ws = client_copy[logintoken].client_ws                            await ws.close()                            continue                        realurl = apiroute.apiserver + '/getreddot_countdown/{0}/{1}/'.format(memberid, logintoken)                        serverdata, clientdata, commandresult = await apiroute.getapiresult(logintoken, realurl)                        # 檢查結果                        if commandresult == pg_general.Packagestatuscode.success and len(clientdata)>0:                            ws = client_copy[logintoken].client_ws                            await ws.send_json({"commandid":3000002,"clientdata":clientdata})                    await asyncio.sleep(0)        except Exception as e:            pg_general.writelog(pg_general.PG_LogerLevel.error, 'reddot_countdown_loop except:{0}'.format(e))        finally:            await asyncio.sleep(5)async def friendonlinestatus_loop(app):    while 1:        try:            client_copy = app["client_dict"].copy()            if client_copy != {}:                for logintoken in client_copy:                    # 發送request到apiserver                    memberid = client_copy[logintoken].memberid                    if memberid is not None:                        # 檢查 memberid 裡面的 logintoken 是否與現在的一致                        redis = app['redis']                        cmp_logintoken = await redis.get_value(memberid)                        if cmp_logintoken != logintoken:                            ws = client_copy[logintoken].client_ws                            await ws.close()                            continue                        realurl = apiroute.apiserver + '/friendonlinestatus/{0}/{1}/'.format(memberid, logintoken)                        serverdata, clientdata, commandresult = await apiroute.getapiresult(logintoken, realurl)                        # 檢查結果                        if commandresult == pg_general.Packagestatuscode.success and len(clientdata)>0:                            ws = client_copy[logintoken].client_ws                            await ws.send_json({"commandid":3000014,"data":clientdata})                    await asyncio.sleep(0)        except Exception as e:            pg_general.writelog(pg_general.PG_LogerLevel.error, 'friendonlinestatus_loop except:{0}'.format(e))        finally:            await asyncio.sleep(10)async def server_to_all_client(app, msg):    copy_client = app["client_dict"].copy().keys()    tStart = time.time()  # 計時開始    for logintoken in copy_client:        try:            await server_to_client(app, msg, logintoken)        except:            pg_general.writelog(pg_general.PG_LogerLevel.warn,                                'server_to_all_client except:{0}'.format(sys.exc_info()[0]))    tEnd = time.time()    if len(copy_client)>0:        pg_general.writelog(pg_general.PG_LogerLevel.debug,                            '{0} send count:{1}, send msg:{2}, cost:{3} sec.'.format(time.strftime("%Y-%m-%d %X"),                                                                                     len(copy_client), msg, (tEnd - tStart)))async def server_to_client(app, msg, logintoken):    try:        # 檢查該連線是否存在        if logintoken in app["client_dict"]:            ws = app["client_dict"][logintoken].client_ws            memberid = app["client_dict"][logintoken].memberid            if memberid is not None:                await ws.send_json(msg)        else:            pg_general.writelog(pg_general.PG_LogerLevel.warn,                                'server_to_client not found name:{0}'.format(name))    except:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'server_to_client except:{0}'.format(sys.exc_info()[0]))async def server_to_channel(app,msg):    try:        data = msg.get('data')        channelindex = data.get('channelindex')        copy_client = app["client_dict"].copy().keys()        for logintoken in copy_client:            if app["client_dict"][logintoken].channelindex == channelindex:                await server_to_client(app,msg,logintoken)    except:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'server_to_client except:{0}'.format(sys.exc_info()[0]))async def bet_hanlder(request):    try:        app = request.app        data = await request.json()        pg_general.writelog(pg_general.PG_LogerLevel.info,                            'bet_hanlder recv:{0}'.format(data))        logintoken = data.get("token")        if logintoken is not None:            q = app["client_dict"][logintoken].queue            await q.put(data)    except Exception as e:        pg_general.writelog(pg_general.PG_LogerLevel.error,                            'bet_hanlder Except: {0} , logintoken: {1}'.format(e,logintoken))    finally:        pg_general.writelog(pg_general.PG_LogerLevel.info,                            'bet_hanlder Respone: 0 , logintoken: {0}'.format(logintoken))        return aiohttp.web.Response(text='0')async def result_handler(request):    try:        app = request.app        data = await request.json()        pg_general.writelog(pg_general.PG_LogerLevel.info,                            'result_handler recv:{0}'.format(data))        logintoken = data.get('token')        ga_obj = app["client_dict"][logintoken].ga_obj        if data.get('has_bonus') == 0:            ga_obj.send_page_view('/result', 'result')        elif data.get('has_bonus') == 1:            ga_obj.send_page_view('/result_bonus', 'result_bonus')        if logintoken is not None:            q = app["client_dict"][logintoken].queue            await q.put(data)    except Exception as e:        pg_general.writelog(pg_general.PG_LogerLevel.error,                            'result_handler Except: {0} , logintoken: {1}'.format(e,logintoken))    finally:        pg_general.writelog(pg_general.PG_LogerLevel.info,                            'result_handler Respone: 0,logintoken: {0}'.format(logintoken))        return aiohttp.web.Response(text='0')async def setmyselfip(app):     while(1):        try:            if env_setting.LOCAL_SERVER==False:                result = await apiroute.setmyselfip_msghandler(app)            else:                result = pg_general.Apiresult.success            if result == pg_general.Apiresult.success:                break        except:            print('set my ip except')        await asyncio.sleep(1)async def boradcasttoall_handler(request):    app = request.app    recvdata = await request.json()    pg_general.writelog(pg_general.PG_LogerLevel.debug, "boradcasttoall_handler recvdata:{0}".format(recvdata))    broadcasttype = recvdata.get('type')    msg_info = recvdata.get('msg')    if msg_info is not None:        q = app['broadcast_queue']        await q.put(recvdata)    return aiohttp.web.Response(text='0')async def initialredis(app):    pg_general.writelog(pg_general.PG_LogerLevel.info, "initial redis server connection start")    redis = PGRedis()    app['redis'] = redis    if redis.initialflag:        pg_general.writelog(pg_general.PG_LogerLevel.info, "initial redis server connection end")    else:        pg_general.writelog(pg_general.PG_LogerLevel.error, "initial redis server connection error")async def check_client_state(app):    while(1):        try:            nowdatetime = datetime.utcnow()            for client in app['client_dict'].keys():                client_info = app['client_dict'][client]                seconds = (nowdatetime - client_info.syncdatetime).seconds                if seconds >30:                    try:                        await client_info.client_ws.close()                    except:                        pass                    try:                        del app['client_dict'][client]                    except:                        pass        except Exception as e:            pass        finally:            await asyncio.sleep(5)async def setdebugmode_handle(request):    app = request.app    id = request.rel_url.query.get('id')    mode = pg_general.converttype(request.rel_url.query.get('mode'),int)    if id != 'UUIIx123kjsdfkxKJKdaddafasdfasdadfJKJ123adf3w423KJKJHbHY*Y*':        return aiohttp.web.HTTPNotFound()    if mode == 0:        env_setting.DEBUG_LOG_MODE = False    elif mode ==1:        env_setting.DEBUG_LOG_MODE = True    return aiohttp.web.Response(text='done')def main(port=PORT):    try:        pg_general.writelog(pg_general.PG_LogerLevel.debug, "lobby server start...")        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)        app = aiohttp.web.Application()        app["broadcast_queue"] = asyncio.Queue(maxsize=-1)        app["logout_queue"] = asyncio.Queue(maxsize=-1)        app["client_dict"] = {}        app['selfip'] = pg_getselfip.get_self_ip()      # 抓自己 ip        app['port'] = port        loop.run_until_complete(initialredis(app))        loop.run_until_complete(setmyselfip(app))        asyncio.ensure_future(broadcastloop(app))        asyncio.ensure_future(logoutloop(app))        asyncio.ensure_future(reddot_countdown_loop(app))        asyncio.ensure_future(friendonlinestatus_loop(app))        asyncio.ensure_future(check_client_state(app))        app.router.add_route('GET', '/lobbyserver', websocket_handler)        app.router.add_route('GET', '/headline/{type}', headline_handler)  # for test        app.router.add_route('GET', '/healthycheck',healthycheck_handler)           # for healthy check        app.router.add_route('GET', '/concurrent_user',concurrent_user_handler)     # for check con current users        app.router.add_route('GET', '/bet/',bet_hanlder)                # for game api server call        app.router.add_route('GET', '/result/',result_handler)          # for game api server call        app.router.add_route('GET', '/broadcasttoall',boradcasttoall_handler)        app.router.add_route('GET', '/setdebugmode/', setdebugmode_handle)        aiohttp.web.run_app(app, host="0.0.0.0", port=port)    except:        pg_general.writelog(pg_general.PG_LogerLevel.warn,                            'main all except:{0}'.format(sys.exc_info()[0]))if __name__ == '__main__':    args = sys.argv    port = None    if len(args)>1:        port = args[1]        port = pg_general.converttype(port,int)    pg_general.loggerinit()    if port is not None:        main(port)    else:        main()